<!-- This file is generated by AI. -->

<!--
  「项目」侧栏页: 配置 (config.txt 摘要) + 引擎 + 模板。

  配置那一节刻意**不做成表单**: 配置的真相来源是 `game/config.txt` 那份文本, 在侧栏里再摆一套
  可编辑字段就多出一个可能与文本不一致的状态 —— 这里只"看一眼 + 一键去改"。引擎与模板则是
  **绑定关系**而不是文件内容, 因此必须在侧栏里能直接切换。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script lang="ts">
  import { requestAlert } from '../confirm';
  import { findBinding } from '../lib/bindings';
  import { engineLabel, resolveProjectEngine } from '../lib/engine';
  import { resolveProjectTemplate, type ProjectTemplateResolution } from '../lib/engineTemplate';
  import { fs } from '../lib/fs';
  import { gameConfigSummary, type GameConfigSummary } from '../lib/gameConfig';
  import { useImageUrl } from '../lib/localImage.svelte';
  import { joinPath } from '../lib/paths';
  import { configPathOf, openProjectConfig, readProjectConfig, switchProjectEngine, switchTemplate } from '../project';
  import { actions, appStore } from '../state/store.svelte';
  import Button from './Button.svelte';
  import Icon from './Icon.svelte';
  import Select from './Select.svelte';

  /** 「项目内置引擎」的取值: 空串是一个**真实选项**, 不是"没选"的占位 —— 项目自己就带一份完整引擎。 */
  const SELF_CONTAINED = '';
  /** 「项目里的模板在本地列表里找不到」时那个只读选项的取值。 */
  const UNKNOWN_TEMPLATE = '__project-template-unknown__';

  const projectPath = $derived(appStore.projectPath);
  const settings = $derived(appStore.settings);
  const bindings = $derived(appStore.projectBindings);
  const engine = $derived(resolveProjectEngine(settings, bindings, projectPath));
  const binding = $derived(projectPath ? findBinding(bindings, projectPath) : undefined);

  let busy = $state(false);
  let summary = $state<GameConfigSummary | null>(null);
  let resolution = $state<ProjectTemplateResolution | null>(null);
  /** 项目目录里是否有 index.html (有就不需要引擎层)。 */
  let hasIndexHtml = $state<boolean | null>(null);
  /** 切换引擎/模板之后 +1, 让下面的读取整组重跑。 */
  let reloadToken = $state(0);

  /*
   * config.txt 的**开着的文档优先**。
   *
   * 侧栏显示的是"当前的项目信息", 而用户可能刚在编辑器里改了 `Game_name` 还没存盘 ——
   * 那时磁盘上那份是旧的。读一下打开文档的内容就能实时跟着走 (存盘后内容不变, 因此不会跳)。
   */
  const configPath = $derived(projectPath ? configPathOf(projectPath) : null);
  const configContent = $derived(
    configPath ? appStore.documents.find((doc) => doc.path === configPath)?.content : undefined
  );

  $effect(() => {
    const path = projectPath;
    // 依赖清单: 项目、配置文本、引擎/模板清单、以及手动刷新令牌
    void configContent;
    void settings.templates;
    void reloadToken;

    if (!path) {
      summary = null;
      hasIndexHtml = null;
      resolution = null;
      return;
    }

    let cancelled = false;
    void (async () => {
      const config = await readProjectConfig(path);
      if (cancelled) return;
      summary = config ? gameConfigSummary(config.entries) : null;

      const stat = await fs.exists(joinPath(path, 'index.html'));
      if (cancelled) return;
      hasIndexHtml = stat.exists && !stat.isDirectory;

      const next = await resolveProjectTemplate(settings, path);
      if (!cancelled) resolution = next;
    })();
    return () => {
      cancelled = true;
    };
  });

  /** 封面图: `Title_img` 指向 `game/background/` 下的文件名 (读不到就显示占位图标)。 */
  const cover = useImageUrl(() =>
    projectPath && summary?.titleImg ? joinPath(projectPath, 'game', 'background', summary.titleImg) : null
  );

  const engineOptions = $derived([
    { value: SELF_CONTAINED, label: hasIndexHtml === false ? '未选择引擎' : '项目内置引擎' },
    ...settings.engines.map((item) => ({ value: item.id, label: engineLabel(item) })),
  ]);

  const template = $derived(resolution?.template ?? null);
  const templateValue = $derived(resolution?.unknownName ? UNKNOWN_TEMPLATE : (template?.id ?? ''));
  const templateOptions = $derived([
    { value: '', label: '跟随引擎默认' },
    // 项目里写着一个本地列表里没有的模板: 把它显示出来, 而不是假装"没设模板"
    ...(resolution?.unknownName ? [{ value: UNKNOWN_TEMPLATE, label: resolution.unknownName }] : []),
    ...settings.templates.map((item) => ({ value: item.id, label: item.name })),
  ]);

  /** 跑一次会改项目绑定的操作, 统一处理 busy / 报错 / 重读。 */
  async function runSwitch(action: () => Promise<void>, failureTitle: string): Promise<void> {
    const path = projectPath;
    if (!path || busy) return;
    busy = true;
    try {
      await action();
      reloadToken += 1;
    } catch (error) {
      requestAlert(failureTitle, String(error));
    } finally {
      busy = false;
    }
  }

  function onSwitchEngine(next: string): void {
    void runSwitch(
      () => switchProjectEngine(projectPath as string, next === SELF_CONTAINED ? null : next),
      '切换引擎失败'
    );
  }

  function onSwitchTemplate(next: string): void {
    // 那个只读的"未知模板"选项被选中时什么都不做 (它只是把项目现状显示出来)
    if (next === UNKNOWN_TEMPLATE) return;
    void runSwitch(() => switchTemplate(projectPath as string, next || null), '切换模板失败');
  }

  function openEngineSettings(): void {
    actions.setSettingsCategory('engine');
    actions.setSettingsOpen(true);
  }

  function openTemplateSettings(): void {
    actions.setSettingsCategory('template');
    actions.setSettingsOpen(true);
  }
</script>

{#if !projectPath}
  <div class="project-tab empty">未打开项目</div>
{:else}
  <div class="project-tab">
    <section class="project-tab-section">
      <!--
        标题叠两个既有类名: `settings-group-title` 给"细下划线 + 小节感", `settings-label` 给
        "弱化色 + 13px"。两条同为单类选择器, 后写的 `.settings-label` 负责颜色 —— 只用前者会亮一档。
      -->
      <h3 class="settings-group-title settings-label">配置</h3>

      <div class="game-info">
        <div class="game-info-cover">
          {#if cover.url}
            <img src={cover.url} alt="" draggable="false" />
          {:else}
            <span class="game-info-cover-empty" aria-hidden="true"><Icon name="Image" size={22} /></span>
          {/if}
        </div>
        <div class="game-info-fields">
          <div class="game-info-row">
            <span class="game-info-label">名称</span>
            <span class="game-info-value" title={summary?.name || '未设置'}>{summary?.name || '未设置'}</span>
          </div>
          <div class="game-info-row">
            <span class="game-info-label">标题图</span>
            <span class="game-info-value game-info-key" title={summary?.titleImg || '未设置'}>
              {summary?.titleImg || '未设置'}
            </span>
          </div>

          <!--
            按钮贴在字段列底部、与封面底边对齐 (见 styles.css 的 `.game-info`)。识别码不在这里显示:
            它是 36 位 UUID, 日常没有可读性, 需要时点"编辑配置"看。
          -->
          <div class="project-tab-actions">
            <Button icon="Edit" disabled={busy} onclick={() => void openProjectConfig(projectPath)}>编辑配置</Button>
          </div>
        </div>
      </div>
    </section>

    <section class="project-tab-section">
      <h3 class="settings-group-title settings-label">引擎</h3>
      <div class="project-tab-template-row">
        <Select
          value={binding?.engineId ?? SELF_CONTAINED}
          options={engineOptions}
          disabled={busy}
          title="这个项目使用的 WebGAL 引擎"
          onchange={onSwitchEngine}
        />
        <Button icon="Settings" disabled={busy} onclick={openEngineSettings}>管理引擎</Button>
      </div>
      {#if engine}
        <span class="project-tab-path" title={engine.path}>{engine.path}</span>
      {:else if hasIndexHtml === false}
        <span class="project-tab-warning">项目目录里没有 index.html，请选择一个引擎目录</span>
      {:else}
        <span class="project-tab-path">使用项目内置引擎（index.html）</span>
      {/if}
    </section>

    <section class="project-tab-section">
      <h3 class="settings-group-title settings-label">模板</h3>
      <div class="project-tab-template-row">
        <Select
          value={templateValue}
          options={templateOptions}
          disabled={busy}
          title="这个项目套用的模板"
          onchange={onSwitchTemplate}
        />
        <Button icon="Settings" disabled={busy} onclick={openTemplateSettings}>管理模板</Button>
      </div>
      {#if template}
        <span class="project-tab-path" title={template.path}>{template.path}</span>
      {:else if resolution?.builtin}
        <span class="project-tab-path">跟随引擎内置模板</span>
      {/if}
    </section>
  </div>
{/if}
